<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$summary=[];$byEvent=[];$byChannel=[];$byStatus=[];$daily=[];
try{$pdo=business_db();comm_step21_ensure($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];comm_step21_sync_events($pdo,$orgId);$summary=comm_step21_metrics($pdo,$orgId,null);$s=$pdo->prepare("SELECT event_type,event_status,COUNT(*) total FROM communication_events WHERE organization_id=? GROUP BY event_type,event_status ORDER BY total DESC,event_type");$s->execute([$orgId]);$byEvent=$s->fetchAll();$s=$pdo->prepare("SELECT channel,status,COUNT(*) total FROM communication_outbox WHERE organization_id=? GROUP BY channel,status ORDER BY channel,status");$s->execute([$orgId]);$byChannel=$s->fetchAll();$s=$pdo->prepare("SELECT status,COUNT(*) total FROM communication_notifications WHERE organization_id=? GROUP BY status ORDER BY total DESC");$s->execute([$orgId]);$byStatus=$s->fetchAll();$s=$pdo->prepare("SELECT DATE(created_at) day,COUNT(*) total,SUM(status='sent') sent,SUM(status='failed') failed FROM communication_outbox WHERE organization_id=? AND created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY DATE(created_at) ORDER BY day DESC");$s->execute([$orgId]);$daily=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Communication Analytics - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="communication_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Communication Analytics</small></span></a><div class="os-top-actions"><a class="os-btn" href="communication_export.php">Export</a><a class="os-btn primary" href="communication_center.php">Communications</a></div></div></header><main class="os-main" style="max-width:1360px;margin:auto"><section class="os-hero s10-hero"><div class="os-kicker">STEP 21 • ANALYTICS</div><h1>Operational alert load and delivery performance.</h1><p>In-app events and external delivery are measured separately so a generated alert is never mistaken for a sent message.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><section class="s10-kpis"><div class="s10-kpi"><small>Open Events</small><strong><?= (int)($summary['open_events']??0) ?></strong><span>current conditions</span></div><div class="s10-kpi"><small>Critical</small><strong><?= (int)($summary['critical_events']??0) ?></strong><span>open critical events</span></div><div class="s10-kpi"><small>Outbox Waiting</small><strong><?= (int)($summary['outbox_waiting']??0) ?></strong><span>queued/manual/provider</span></div><div class="s10-kpi"><small>Failed</small><strong><?= (int)($summary['failed']??0) ?></strong><span>delivery failures</span></div><div class="s10-kpi"><small>Sent / 30d</small><strong><?= (int)($summary['sent_30d']??0) ?></strong><span>external messages</span></div></section><section class="s10-grid"><article class="s10-card s10-span-6"><h2>Event Type / State</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Event</th><th>State</th><th>Total</th></tr></thead><tbody><?php if(!$byEvent):?><tr><td colspan="3">No event history.</td></tr><?php endif;?><?php foreach($byEvent as $r):?><tr><td><?=comm_step21_h($r['event_type'])?></td><td><?=comm_step21_h(strtoupper((string)$r['event_status']))?></td><td><?=$r['total']?></td></tr><?php endforeach;?></tbody></table></div></article><article class="s10-card s10-span-6"><h2>Outbox Channel / State</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Channel</th><th>State</th><th>Total</th></tr></thead><tbody><?php if(!$byChannel):?><tr><td colspan="3">No external messages.</td></tr><?php endif;?><?php foreach($byChannel as $r):?><tr><td><?=comm_step21_h(strtoupper((string)$r['channel']))?></td><td><?=comm_step21_h(strtoupper(str_replace('_',' ',(string)$r['status'])))?></td><td><?=$r['total']?></td></tr><?php endforeach;?></tbody></table></div></article><article class="s10-card s10-span-4"><h2>In-App States</h2><div class="pp-list"><?php if(!$byStatus):?><div class="pp-empty">No notifications.</div><?php endif;?><?php foreach($byStatus as $r):?><div class="pp-source"><div><b><?=comm_step21_h(strtoupper((string)$r['status']))?></b><small>notification state</small></div><span class="pp-badge"><?=$r['total']?></span></div><?php endforeach;?></div></article><article class="s10-card s10-span-8"><h2>External Outbox / Last 30 Days</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Created</th><th>Sent</th><th>Failed</th></tr></thead><tbody><?php if(!$daily):?><tr><td colspan="4">No recent external messages.</td></tr><?php endif;?><?php foreach($daily as $r):?><tr><td><?=comm_step21_h($r['day'])?></td><td><?=$r['total']?></td><td><?=$r['sent']?></td><td><?=$r['failed']?></td></tr><?php endforeach;?></tbody></table></div></article></section></main></body></html>